Only classes 0-7 appear, and the grids look like two hidden tables f(a), g(b) joined by a skill-specific operation (skill 1 looks like max, skill 0 a clipped sum, skill 2 an absolute difference). I print the full grids to read the rules off them.
```python
def silu(x): return x/(1+np.exp(-x))
W={n:load(n) for n in NAMES}
def fwd(W,X):
    h=silu(X@W["l1.weight"].T+W["l1.bias"]); h=silu(h@W["l2.weight"].T+W["l2.bias"]); return h@W["l3.weight"].T+W["l3.bias"]
A,B=np.meshgrid(np.arange(32),np.arange(32),indexing="ij")
G=[]
for s in range(4):
    X=np.zeros((1024,68));X[np.arange(1024),A.ravel()]=1;X[np.arange(1024),32+B.ravel()]=1;X[:,64+s]=1
    G.append(fwd(W,X).argmax(1).reshape(32,32))
np.save("grid.npy",np.array(G))
for s in range(4):
    print("skill",s)
    for r in G[s]: print("".join(map(str,r)))
