Rows and columns seem to fall into few types, so I group them by Hamming distance (one pass, no fitting) and read each skill as a table over row type and column type.
```python
G=np.load("grid.npy")
def groups(M,th):
    lab=-np.ones(len(M),int);k=0
    for i in range(len(M)):
        if lab[i]<0:
            d=(M!=M[i]).sum(1); lab[(d<=th)&(lab<0)]=k; k+=1
    return lab,k
np.set_printoptions(linewidth=200)
res={}
for s in range(4):
    for th in [6,10]:
        ra,ka=groups(G[s],th); rb,kb=groups(G[s].T,th)
        print("skill",s,"th",th,"rowtypes",ka,"coltypes",kb)
    ra,ka=groups(G[s],8); rb,kb=groups(G[s].T,8)
    ma=[G[s][ra==i].mean() for i in range(ka)]; oa=np.argsort(np.argsort(ma)); ra=oa[ra]
    mb=[G[s][:,rb==i].mean() for i in range(kb)]; ob=np.argsort(np.argsort(mb)); rb=ob[rb]
    T=np.zeros((ka,kb),int);C=np.zeros((ka,kb))
    for i in range(ka):
        for j in range(kb):
            v=G[s][np.ix_(ra==i,rb==j)].ravel()
            if len(v): T[i,j]=np.bincount(v).argmax();C[i,j]=(v==T[i,j]).mean()
    rec=T[ra][:,rb]
    print("row lev",ra);print("col lev",rb);print("sizes",np.bincount(ra),np.bincount(rb))
    print(T);print("agree with grid",(rec==G[s]).mean().round(4),"min purity",C.min().round(2))
    res[s]=(ra,rb,T)
