Skill 2 now reads within 0.2-0.4 of the scan, but my variable S clobbered the hinge scale, so nothing was saved and that EVAL was stale. I fix that, take one more fixed read for skill 2, read skills 0 and 3 cell by cell the same way, and evaluate.
```python
exec(open("hand.py").read())
Es=np.load("soft.npy");G=np.load("grid.npy")
T=dict(np.load("tables.npz"))
cl=lambda t:np.clip(np.floor(t),0,7)
def rd2(E,me,other):
    out=me.copy()
    for i in range(32):
        d=me[i]-other;c=(abs(d)>1.5)&(E[i]>0.7)&(E[i]<6.3)
        if c.sum()>=3: out[i]=np.median(other[c]+np.sign(d[c])*(E[i][c]+0.5))
    return out
T["v2"]=rd2(Es[2].T,T["v2"],T["u2"])
def rd0(E,other,me):
    out=me.copy()
    for i in range(32):
        c=(E[i]>0.7)&(E[i]<6.3)
        if c.sum()>=3: out[i]=np.median(E[i][c]+0.5-other[c])
    return out
T["u0"]=rd0(Es[0],T["v0"],T["u0"]);T["v0"]=rd0(Es[0].T,T["u0"],T["v0"])
def rd3(E,other,me):
    out=me.copy()
    for i in range(32):
        c=(E[i]>0.7)&(E[i]<6.3)&(other>0.3)
        if c.sum()>=3: out[i]=np.median((E[i][c]+0.5)/other[c])
    return out
T["u3"]=rd3(Es[3],T["v3"],T["u3"]);T["v3"]=rd3(Es[3].T,T["u3"],T["v3"])
np.savez("tables.npz",**T)
R=[cl(T["u0"][:,None]+T["v0"][None,:]),np.maximum(T["u1"][:,None],T["v1"][None,:]),cl(abs(T["u2"][:,None]-T["v2"][None,:])),cl(T["u3"][:,None]*T["v3"][None,:])]
for s in range(4): print("skill",s,"rule vs old grid",(R[s]==G[s]).mean().round(4),"u",T[f"u{s}"].min().round(2),T[f"u{s}"].max().round(2),"v",T[f"v{s}"].min().round(2),T[f"v{s}"].max().round(2))
Ed,n,owner=build(T,save_edit);print("neurons",n,np.bincount(owner[owner>=0]))
for k,v in Ed.items(): save_edit(k,v)
np.save("owner.npy",owner)
H=grids(Ed)
for s in range(4): print("skill",s,"written net vs rule",(H[s]==R[s]).mean().round(4))
